create or replace function public.admin_list_access_requests()
returns table(id uuid,email text,first_name text,last_name text,role public.app_role,access_status text,active boolean,requested_at timestamptz,approved_at timestamptz,member_id uuid)
language plpgsql stable security definer set search_path='' as $$ begin if not public.is_admin() then raise exception 'Accès administrateur requis'; end if; return query select p.id,u.email::text,p.first_name,p.last_name,p.role,p.access_status,p.active,p.requested_at,p.approved_at,p.member_id from public.profiles p left join auth.users u on u.id=p.id order by case p.access_status when 'pending' then 0 else 1 end,p.requested_at desc nulls last; end; $$;
create or replace function public.admin_set_access_request(target_profile_id uuid,decision text,new_role public.app_role default null,linked_member_id uuid default null) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_admin() then raise exception 'Accès administrateur requis'; end if; if decision not in ('approved','rejected','suspended','pending') then raise exception 'Décision invalide'; end if; if decision='approved' and new_role is null then raise exception 'Un rôle doit être choisi'; end if; update public.profiles p set access_status=decision,active=(decision='approved'),role=coalesce(new_role,p.role),member_id=coalesce(linked_member_id,p.member_id),approved_at=case when decision='approved' then now() else p.approved_at end,approved_by=case when decision='approved' then auth.uid() else p.approved_by end,updated_at=now() where p.id=target_profile_id; if not found then raise exception 'Profil introuvable'; end if; end; $$;
revoke all on function public.admin_list_access_requests() from public,anon; revoke all on function public.admin_set_access_request(uuid,text,public.app_role,uuid) from public,anon; grant execute on function public.admin_list_access_requests() to authenticated; grant execute on function public.admin_set_access_request(uuid,text,public.app_role,uuid) to authenticated;